class DiagnosisProbe:
    def __init__(self, view, device):
        self.view, self.device = view, device

    def run_full_diagnosis(self, train_loader):
        state = capture_execution_state(self.view.model)
        metrics, definitions = {}, calibration_definitions()
        try:
            self.view.model.eval()
            cached = bounded_training_cache(train_loader, max_batches=2)
            cases = select_identifiable_cases(cached, max_users=16, seed=42)
            # Correct reference: maximum occupied index, never count-1.
            reference = evaluate_correct_adapter(cases)
            controls = run_unchanged_and_identity_controls(cases, reference)
            metrics['controls'] = controls
            if controls.pass_required_checks:
                for fault in ['wrong_readout', 'future_feature_mix', 'constant_features']:
                    if calibration_budget_exhausted():
                        record_missing(metrics, fault, 'Calibration budget exhausted')
                        continue
                    # Callable uses frozen weights; no new fitted model or checkpoint.
                    with scoped_diagnostic_variant(self.view, fault) as variant:
                        witness = measure_fault_reachability(variant, cases, reference)
                        if not witness.observable:
                            record_unreachable(metrics, fault, witness.reason)
                            continue
                        alarms = run_existing_probes(variant, cases)
                        record_fault_probe_matrix(metrics, fault, witness, alarms)
                record_false_alarms(metrics, controls)
                run_existing_staged_patching_with_remaining_budget(metrics)
            else:
                mark_affected_results_invalid(metrics, controls)
        finally:
            remove_all_temporary_hooks()
            restore_execution_state(self.view.model, state)
        return {'metrics': metrics, 'metric_definitions': definitions}

def diagnosis_interpreter_prompt(raw_diagnosis):
    return build_evidence_linked_prompt(
        raw_diagnosis['metrics'], raw_diagnosis['metric_definitions'],
        require_reachability_denominators=True,
        forbid_validation_or_user_intent_inference=True)
